using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.Rendering; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class ClassesController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(string? q){var x=db.CourseClasses.Include(c=>c.Course).Include(c=>c.Instructor).ThenInclude(i=>i!.User).AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.ClassName.Contains(q)||c.ClassCode.Contains(q));return View(await x.OrderByDescending(c=>c.StartDate).ToListAsync());} public async Task<IActionResult> Create(){await Lists();return View("Form",new CourseClass{StartDate=DateTime.Today.AddDays(30),EndDate=DateTime.Today.AddDays(120),RegistrationOpenAt=DateTime.Now,RegistrationCloseAt=DateTime.Now.AddDays(20),MaxCapacity=30});} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(CourseClass m){Validate(m);if(await db.CourseClasses.AnyAsync(x=>x.ClassCode==m.ClassCode))ModelState.AddModelError(nameof(m.ClassCode),"Mã lớp đã tồn tại.");if(!ModelState.IsValid){await Lists();return View("Form",m);}db.Add(m);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var m=await db.CourseClasses.FindAsync(id);if(m==null)return NotFound();await Lists();return View("Form",m);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,CourseClass m){if(id!=m.ClassId)return BadRequest();var old=await db.CourseClasses.AsNoTracking().SingleAsync(x=>x.ClassId==id);if(m.MaxCapacity<old.CurrentEnrollment)ModelState.AddModelError(nameof(m.MaxCapacity),"Sĩ số tối đa không thể thấp hơn số đang đăng ký.");m.CurrentEnrollment=old.CurrentEnrollment;Validate(m);if(!ModelState.IsValid){await Lists();return View("Form",m);}db.Update(m);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} private void Validate(CourseClass m){if(m.StartDate>m.EndDate)ModelState.AddModelError(nameof(m.EndDate),"Ngày kết thúc phải sau ngày bắt đầu.");if(m.RegistrationOpenAt>=m.RegistrationCloseAt)ModelState.AddModelError(nameof(m.RegistrationCloseAt),"Thời gian đóng phải sau thời gian mở.");} private async Task Lists(){ViewBag.Courses=new SelectList(await db.Courses.ToListAsync(),"CourseId","CourseName");ViewBag.Instructors=new SelectList(await db.Instructors.Include(x=>x.User).ToListAsync(),"InstructorId","User.FullName");} }
